export function skillsWorld(state){
 const definitions=[['crafting','Crafting','Collect completed crafting jobs.'],['sharpshooting','Sharpshooting','Earn score-based range rewards.'],['lockpicking','Lockpicking','Successfully free players from Blackwater Island.']].map(([id,name,description],i)=>({id,name,description,xp_to_20:10000,version:1,display_order:i+1}));
 const ledger=[],requests=new Map();let rate=10;
 const threshold=(l,t)=>l-1+Math.floor((t-19)*(l-1)*(l-1)/361);
 const award=(skill_id,source_id,delta,description)=>{if(delta<=0||ledger.some(r=>r.skill_id===skill_id&&r.source_id===source_id))return;ledger.push({id:skill_id+':'+source_id,season_id:state.season.id,skill_id,source_id,delta,description,created_at:new Date().toISOString()});};
 const read=()=>({season:state.season,player_id:state.player.id,max_level:20,server_time:new Date().toISOString(),can_manage:state.permissions.includes('roles.manage'),crafting_xp_per_minute:rate,skills:definitions.map(s=>{const xp=ledger.filter(r=>r.skill_id===s.id&&r.season_id===state.season.id).reduce((sum,r)=>sum+r.delta,0),thresholds=Array.from({length:20},(_,i)=>({level:i+1,xp:threshold(i+1,s.xp_to_20)})),level=thresholds.filter(t=>t.xp<=xp).at(-1).level;return{...s,xp,level,level_xp:threshold(level,s.xp_to_20),next_level_xp:level===20?null:threshold(level+1,s.xp_to_20),thresholds};}),recent:ledger.filter(r=>r.season_id===state.season.id).slice(-20).reverse()});
 const manage=p=>{if(!state.permissions.includes('roles.manage'))return{error:'Owner skill-management permission required.'};const key=JSON.stringify(p),old=requests.get(p.request_id);if(old)return old.key===key?{...old.result,state:read()}:{error:'This save reference was already used.'};const s=definitions.find(s=>s.id===p.skill_id);if(!s||s.version!==p.version)return{error:'These settings changed. Refresh before saving.'};if(!Number.isSafeInteger(p.xp_to_20)||p.xp_to_20<19||p.xp_to_20>1e9)return{error:'Choose a whole XP target between 19 and 1,000,000,000.'};if(!p.reason||p.reason.trim().length<5)return{error:'Add an audit reason of 5 to 500 characters.'};if(s.id==='crafting'){if(p.expected_crafting_rate!==rate)return{error:'Crafting rewards changed. Refresh before saving.'};if(!Number.isSafeInteger(p.crafting_xp_per_minute)||p.crafting_xp_per_minute<1||p.crafting_xp_per_minute>10000)return{error:'Invalid crafting XP rate.'};rate=p.crafting_xp_per_minute;}s.xp_to_20=p.xp_to_20;s.version++;const result={message:s.name+' progression saved. Earned XP is preserved.'};requests.set(p.request_id,{key,result});return{...result,state:read()};};
 const setup=p=>{if(p.awards)for(const [id,xp]of Object.entries(p.awards))award(id,'setup-'+ledger.length,xp,'Recorded skill practice');if(p.player)state.permissions=[];if(p.season){state.season.id=p.season;state.season.name='Next Season';}};
 return{read,manage,award,rate:()=>rate,setup};
}
